(()=>{'use strict';if(window.__VELARIS_V003__)return;window.__VELARIS_V003__=true;const VERSION='0.0.3';const rx={continue:/continue\s*watching|weiterschauen|weiter\s*schauen|fortsetzen/i,next:/next\s*up|als\s*n[aä]chstes|n[aä]chste\s*folgen/i,latest:/latest|recently\s*added|neu\s*hinzugef[uü]gt|zuletzt\s*hinzugef[uü]gt|neueste/i};let timer=0,observer=null,heroSource=null;const q=(r,s)=>r?.querySelector?.(s)||null,qa=(r,s)=>r?.querySelectorAll?Array.from(r.querySelectorAll(s)):[],txt=n=>(n?.textContent||'').replace(/\s+/g,' ').trim();function classify(section){const title=txt(q(section,'.sectionTitle'));section.classList.remove('velaris-row--continue','velaris-row--next','velaris-row--latest','velaris-row--featured');let kind='standard';if(rx.continue.test(title))kind='continue';else if(rx.next.test(title))kind='next';else if(rx.latest.test(title))kind='latest';section.dataset.velarisKind=kind;if(kind!=='standard')section.classList.add(`velaris-row--${kind}`)}function scroller(section){const list=qa(section,'.emby-scroller,.itemsContainer');return list.find(el=>el.scrollWidth>el.clientWidth+24)||list[0]||null}function rails(section){if(q(section,'.velaris-rail-controls'))return;const head=q(section,'.sectionTitleContainer'),rail=scroller(section);if(!head||!rail)return;const wrap=document.createElement('div');wrap.className='velaris-rail-controls';[-1,1].forEach(dir=>{const b=document.createElement('button');b.type='button';b.className='velaris-rail-button emby-button';b.setAttribute('aria-label',dir<0?'Zurück':'Weiter');b.textContent=dir<0?'‹':'›';b.onclick=e=>{e.preventDefault();e.stopPropagation();rail.scrollBy({left:Math.max(rail.clientWidth*.82,320)*dir,behavior:'smooth'})};wrap.appendChild(b)});head.style.position='relative';head.appendChild(wrap)}function cardTitle(card){return txt(q(card,'.cardText:first-of-type'))||card.getAttribute('aria-label')||card.getAttribute('title')||'Entdecken'}function cardImage(card){const img=q(card,'img');if(img?.currentSrc||img?.src)return img.currentSrc||img.src;const box=q(card,'.cardImageContainer,.cardImage');const bg=box?getComputedStyle(box).backgroundImage:'';const m=bg&&bg!=='none'?bg.match(/url\(["']?(.*?)["']?\)/):null;return m?.[1]||''}function heroCard(sections){const preferred=sections.filter(s=>!['continue','next'].includes(s.dataset.velarisKind));for(const s of preferred){const c=qa(s,'.card').find(card=>cardImage(card));if(c)return c}return qa(document,'.card').find(card=>cardImage(card))||null}function trigger(card,play){if(!card?.isConnected)return;if(play){const p=q(card,'.cardOverlayFab-primary,[data-action="play"],.btnPlay');if(p)return p.click()}(q(card,'a[href],button[data-id],.cardImageContainer')||card).click()}function buildHero(home,sections){const card=heroCard(sections);if(!card)return;const image=cardImage(card);if(!image)return;let hero=q(home,'.velaris-hero');if(!hero){hero=document.createElement('section');hero.className='velaris-hero';hero.innerHTML='<div class="velaris-hero__art"></div><div class="velaris-hero__content"><div class="velaris-hero__eyebrow">Velaris Spotlight</div><h1 class="velaris-hero__title"></h1><div class="velaris-hero__meta">Aus deiner Mediathek — kuratiert für einen cineastischen Start.</div><div class="velaris-hero__actions"></div></div>';const actions=q(hero,'.velaris-hero__actions'),play=document.createElement('button'),details=document.createElement('button');play.type=details.type='button';play.className='velaris-hero__button velaris-hero__button--primary emby-button';details.className='velaris-hero__button emby-button';play.textContent='▶ Abspielen';details.textContent='ⓘ Details';play.onclick=()=>trigger(heroSource,true);details.onclick=()=>trigger(heroSource,false);actions.append(play,details);const first=sections[0];first?.parentElement?.insertBefore(hero,first)}heroSource=card;q(hero,'.velaris-hero__art').style.backgroundImage=`url(${JSON.stringify(image)})`;q(hero,'.velaris-hero__title').textContent=cardTitle(card)}function reorder(sections){const parent=sections[0]?.parentElement;if(!parent||sections.some(s=>s.parentElement!==parent))return;const cont=sections.find(s=>s.dataset.velarisKind==='continue'),next=sections.find(s=>s.dataset.velarisKind==='next'),hero=q(parent,'.velaris-hero'),anchor=hero?.nextSibling||sections[0];[cont,next].filter(Boolean).reverse().forEach(row=>parent.insertBefore(row,anchor))}function brand(){const header=q(document,'.skinHeader');if(!header||q(header,'.velaris-brand'))return;const b=document.createElement('div');b.className='velaris-brand';b.textContent='Velaris';header.appendChild(b)}function enhance(){document.body?.classList.add('velaris-active');brand();const home=q(document,'.homePage');if(!home)return;const sections=qa(home,'.verticalSection');if(!sections.length)return;sections.forEach(s=>{classify(s);rails(s)});const featured=sections.find(s=>!['continue','next'].includes(s.dataset.velarisKind));featured?.classList.add('velaris-row--featured');buildHero(home,sections);reorder(sections);home.dataset.velarisEnhanced=VERSION}function schedule(ms=80){clearTimeout(timer);timer=setTimeout(enhance,ms)}function boot(){enhance();observer=new MutationObserver(ms=>{if(ms.some(m=>m.addedNodes.length||m.removedNodes.length))schedule(90)});observer.observe(document.documentElement,{childList:true,subtree:true});addEventListener('hashchange',()=>schedule(50),{passive:true});addEventListener('popstate',()=>schedule(50),{passive:true});window.Velaris=Object.freeze({version:VERSION,refresh:enhance,stop(){observer?.disconnect();observer=null}});console.info(`[Velaris] v${VERSION} active`)}document.readyState==='loading'?document.addEventListener('DOMContentLoaded',boot,{once:true}):boot()})();
